META = dict(
    n=13, featured=[2, 27], name='The Field and the Knower of the Field', skt_name='क्षेत्रक्षेत्रज्ञविभागयोगः', roman_name='Kshetra Kshetrajna Vibhaga Yoga',
    outline="Verses 1–6: the body is the field, and the one who knows it is the knower of the field; 7–11: twenty qualities that together are called knowledge; 12–18: Brahman, the thing to be known; 19–23: nature and the spirit; 24–26: different ways of seeing the Self; 27–34: the one Lord, the same in all beings, who does not act and is not stained. Some editions begin this chapter with a question from Arjuna and count 35 verses; the numbering here follows the 34-verse count.",
)
# Line breaks or spacing only (the tool checks that no letter changes).
LINES = {
    11: ['अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम्', 'एतज्ज्ञानमिति प्रोक्तमज्ञानं यदतोऽन्यथा'],   # the copies leave out the avagraha
    23: ['य एवं वेत्ति पुरुषं प्रकृतिं च गुणैः सह', 'सर्वथा वर्तमानोऽपि न स भूयोऽभिजायते'],        # the copies run गुणैः and सह together
}
V = {
1: ("""इदं शरीरम् = this body | कौन्तेय = O son of Kunti (Arjuna) | क्षेत्रम् इति अभिधीयते = is called the field | एतत् यः वेत्ति = the one who knows it | तं प्राहुः क्षेत्रज्ञः इति = is called the knower of the field | तत्-विदः = by those who understand these things""",
    "Krishna said: This body, Arjuna, is called the field. The one who knows it is called the knower of the field by those who understand these things."),
2: ("""क्षेत्रज्ञं च अपि मां विद्धि = know me also as the knower of the field | सर्व-क्षेत्रेषु = in all fields | भारत = O descendant of Bharata (Arjuna) | क्षेत्र-क्षेत्रज्ञयोः ज्ञानम् = knowledge of the field and its knower | यत् तत् ज्ञानं मतं मम = that, in my view, is true knowledge""",
    "Know me, Arjuna, as the knower of the field in every field. Knowledge of the field and of its knower is, in my view, true knowledge."),
3: ("""तत् क्षेत्रं यत् च = what that field is | यादृक् च = and what it is like | यत्-विकारि = what its changes are | यतः च यत् = and where it comes from | सः च यः = and who he, the knower, is | यत्-प्रभावः च = and what his powers are | तत् समासेन मे शृणु = hear that from me in brief""",
    "Hear from me in brief what the field is, what it is like, how it changes and where it comes from, and also who the knower is and what his powers are."),
4: ("""ऋषिभिः बहुधा गीतम् = it has been sung by the sages in many ways | छन्दोभिः विविधैः पृथक् = in various separate Vedic hymns | ब्रह्म-सूत्र-पदैः च एव = and in the words of the Brahma Sutras | हेतुमद्भिः विनिश्चितैः = which are well reasoned and certain""",
    "The sages have sung of this in many ways, in various Vedic hymns, and also in the well-reasoned and certain words of the Brahma Sutras."),
5: ("""महा-भूतानि = the five great elements | अहङ्कारः = the sense of “I” | बुद्धिः = the intellect | अव्यक्तम् एव च = and unseen nature | इन्द्रियाणि दश एकं च = the ten senses and the one, the mind | पञ्च च इन्द्रिय-गोचराः = and the five objects of the senses""",
    "The five great elements, the sense of “I”, the intellect and unseen nature; the ten senses and the mind, and the five objects of the senses;"),
6: ("""इच्छा द्वेषः = desire, dislike | सुखं दुःखम् = pleasure, pain | सङ्घातः = the body as a whole | चेतना धृतिः = consciousness, steadiness | एतत् क्षेत्रं समासेन = this, in brief, is the field | स-विकारम् उदाहृतम् = described with its changes""",
    "desire and dislike, pleasure and pain, the body as a whole, consciousness and steadiness: this, in brief, is the field, together with its changes."),
7: ("""अमानित्वम् = humility | अदम्भित्वम् = freedom from pretence | अहिंसा = non-violence | क्षान्तिः = patience | आर्जवम् = honesty | आचार्य-उपासनम् = service to the teacher | शौचम् = purity | स्थैर्यम् = steadiness | आत्म-विनिग्रहः = self-control""",
    "Humility, freedom from pretence, non-violence, patience, honesty, service to the teacher, purity, steadiness and self-control;"),
8: ("""इन्द्रिय-अर्थेषु वैराग्यम् = detachment from the objects of the senses | अनहङ्कारः एव च = and freedom from ego | जन्म-मृत्यु-जरा-व्याधि-दुःख-दोष-अनुदर्शनम् = seeing the suffering in birth, death, old age and illness""",
    "detachment from the objects of the senses, freedom from ego, and seeing clearly the suffering in birth, death, old age and illness;"),
9: ("""असक्तिः = non-attachment | अनभिष्वङ्गः = not clinging | पुत्र-दार-गृह-आदिषु = to children, spouse, home and the rest | नित्यं च सम-चित्तत्वम् = and a mind that is always even | इष्ट-अनिष्ट-उपपत्तिषु = when wanted or unwanted things happen""",
    "non-attachment, and not clinging to children, spouse, home and the rest; a mind that stays even whether wanted or unwanted things happen;"),
10: ("""मयि च अनन्य-योगेन = and for me, with undivided yoga | भक्तिः अव्यभिचारिणी = devotion that never strays | विविक्त-देश-सेवित्वम् = living in quiet places | अरतिः जन-संसदि = no taste for crowds""",
    "devotion to me that never strays, with undivided yoga; a liking for quiet places and no taste for crowds;"),
11: ("""अध्यात्म-ज्ञान-नित्यत्वम् = constancy in knowledge of the Self | तत्त्व-ज्ञान-अर्थ-दर्शनम् = seeing the purpose of knowing the truth | एतत् ज्ञानम् इति प्रोक्तम् = this is declared to be knowledge | अज्ञानं यत् अतः अन्यथा = and what is other than this is ignorance""",
    "constancy in knowledge of the Self, and seeing what knowledge of the truth is for: this is declared to be knowledge. Whatever is otherwise is ignorance."),
12: ("""ज्ञेयं यत् तत् प्रवक्ष्यामि = I shall tell you what is to be known | यत् ज्ञात्वा अमृतम् अश्नुते = knowing which one reaches immortality | अनादिमत् परं ब्रह्म = the supreme Brahman, which has no beginning | न सत् तत् न असत् उच्यते = it is said to be neither being nor non-being""",
    "I shall tell you what is to be known, knowing which a person reaches immortality. It is the supreme Brahman, which has no beginning. It is said to be neither being nor non-being."),
13: ("""सर्वतः पाणि-पादं तत् = it has hands and feet everywhere | सर्वतः अक्षि-शिरः-मुखम् = eyes, heads and faces everywhere | सर्वतः श्रुतिमत् = ears everywhere | लोके सर्वम् आवृत्य तिष्ठति = it stands, covering everything in the world""",
    "It has hands and feet everywhere, eyes, heads and faces everywhere, and ears everywhere. It stands in the world, covering everything."),
14: ("""सर्व-इन्द्रिय-गुण-आभासम् = it shines through the working of all the senses | सर्व-इन्द्रिय-विवर्जितम् = yet has no senses | असक्तम् = unattached | सर्व-भृत् च एव = yet supporting all | निर्गुणम् = free from the gunas | गुण-भोक्तृ च = yet experiencing the gunas""",
    "It shines through the working of all the senses, yet it has no senses. It is unattached, yet it supports everything. It is free from the gunas, yet it experiences them."),
15: ("""बहिः अन्तः च भूतानाम् = outside and inside beings | अचरं चरम् एव च = unmoving and also moving | सूक्ष्मत्वात् तत् अविज्ञेयम् = because it is subtle it cannot be grasped | दूर-स्थं च अन्तिके च तत् = it is far away and also near""",
    "It is outside beings and inside them. It does not move, and yet it moves. It is too subtle to be grasped. It is far away, and it is also near."),
16: ("""अविभक्तं च भूतेषु = undivided among beings | विभक्तम् इव च स्थितम् = yet standing as if divided | भूत-भर्तृ च तत् ज्ञेयम् = it is to be known as the supporter of beings | ग्रसिष्णु प्रभविष्णु च = which takes them back and brings them forth""",
    "It is undivided, yet it seems to be divided among beings. Know it as the supporter of all beings, which takes them back into itself and brings them forth again."),
17: ("""ज्योतिषाम् अपि तत् ज्योतिः = it is the light of all lights | तमसः परम् उच्यते = said to be beyond darkness | ज्ञानं ज्ञेयं ज्ञान-गम्यम् = it is knowledge, what is to be known, and what knowledge leads to | हृदि सर्वस्य विष्ठितम् = it is seated in the heart of everyone""",
    "It is the light of all lights, and is said to be beyond darkness. It is knowledge, the thing to be known and the goal of knowledge, and it is seated in the heart of everyone."),
18: ("""इति क्षेत्रं तथा ज्ञानं ज्ञेयं च = so the field, knowledge and what is to be known | उक्तं समासतः = have been described in brief | मत्-भक्तः एतत् विज्ञाय = my devotee, understanding this | मत्-भावाय उपपद्यते = becomes fit for my state""",
    "So the field, knowledge and what is to be known have been described in brief. My devotee who understands this becomes fit to reach my state."),
19: ("""प्रकृतिं पुरुषं च एव = nature (prakriti) and the spirit (purusha) | विद्धि अनादी उभौ अपि = know that both have no beginning | विकारान् च गुणान् च एव = and all changes and the gunas | विद्धि प्रकृति-सम्भवान् = know to be born of nature""",
    "Know that nature and the spirit both have no beginning. Know also that all changes and the gunas are born of nature."),
20: ("""कार्य-कारण-कर्तृत्वे = in producing the body and the senses and their work | हेतुः प्रकृतिः उच्यते = nature is said to be the cause | पुरुषः सुख-दुःखानां भोक्तृत्वे = the spirit, in the experiencing of pleasure and pain | हेतुः उच्यते = is said to be the cause""",
    "Nature is said to be the cause behind the body and the senses and what they do. The spirit is said to be the cause behind the experience of pleasure and pain."),
21: ("""पुरुषः प्रकृति-स्थः हि = for the spirit, seated in nature | भुङ्क्ते प्रकृति-जान् गुणान् = experiences the gunas born of nature | कारणं गुण-सङ्गः अस्य = its attachment to the gunas is the cause | सत्-असत्-योनि-जन्मसु = of its births in good and bad wombs""",
    "The spirit, seated in nature, experiences the gunas born of nature. Its attachment to the gunas is the cause of its birth in good and bad conditions."),
22: ("""उपद्रष्टा = the witness | अनुमन्ता च = the one who permits | भर्ता भोक्ता = the supporter, the experiencer | महेश्वरः = the great Lord | परमात्मा इति च अपि उक्तः = and also called the supreme Self | देहे अस्मिन् पुरुषः परः = is the supreme spirit in this body""",
    "The supreme spirit in this body is called the witness, the one who permits, the supporter, the experiencer, the great Lord and the supreme Self."),
23: ("""यः एवं वेत्ति पुरुषम् = whoever knows the spirit in this way | प्रकृतिं च गुणैः सह = and nature along with the gunas | सर्वथा वर्तमानः अपि = however he may be living | न सः भूयः अभिजायते = is not born again""",
    "Whoever knows the spirit in this way, and nature with its gunas, is not born again, however that person may be living now."),
24: ("""ध्यानेन आत्मनि पश्यन्ति केचित् आत्मानम् आत्मना = some see the Self within themselves by meditation, through the mind | अन्ये सांख्येन योगेन = others by the yoga of knowledge (sankhya) | कर्म-योगेन च अपरे = and others by the yoga of action""",
    "Some see the Self within themselves through meditation. Others see it through the yoga of knowledge, and others through the yoga of action."),
25: ("""अन्ये तु एवम् अजानन्तः = but others, who do not know in this way | श्रुत्वा अन्येभ्यः उपासते = hear from others and worship | ते अपि च अतितरन्ति एव मृत्युम् = they too cross beyond death | श्रुति-परायणाः = devoted to what they have heard""",
    "Others, who do not know it in these ways, hear of it from others and worship. They too cross beyond death, through their devotion to what they have heard."),
26: ("""यावत् सञ्जायते किञ्चित् सत्त्वम् = whatever being is born | स्थावर-जङ्गमम् = unmoving or moving | क्षेत्र-क्षेत्रज्ञ-संयोगात् = from the union of the field and its knower | तत् विद्धि = know that it comes | भरतर्षभ = O best of the Bharatas (Arjuna)""",
    "Whatever is born, Arjuna, whether it moves or not, know that it comes from the union of the field and the knower of the field."),
27: ("""समं सर्वेषु भूतेषु तिष्ठन्तं परमेश्वरम् = the supreme Lord living equally in all beings | विनश्यत्सु अविनश्यन्तम् = not perishing when they perish | यः पश्यति सः पश्यति = whoever sees this truly sees""",
    "Whoever sees the supreme Lord living equally in all beings, and not perishing when they perish, truly sees."),
28: ("""समं पश्यन् हि सर्वत्र = for seeing equally, everywhere | समवस्थितम् ईश्वरम् = the Lord present | न हिनस्ति आत्मना आत्मानम् = one does not harm the Self by the self | ततः याति परां गतिम् = and so reaches the highest goal""",
    "Seeing the same Lord present everywhere, a person does no harm to their own Self, and so reaches the highest goal."),
29: ("""प्रकृत्या एव च कर्माणि क्रियमाणानि सर्वशः = that all actions are done by nature alone | यः पश्यति = whoever sees | तथा आत्मानम् अकर्तारम् = and that the Self does nothing | सः पश्यति = truly sees""",
    "Whoever sees that all actions are done by nature alone, and that the Self does nothing, truly sees."),
30: ("""यदा भूत-पृथक्-भावम् = when the many separate states of beings | एक-स्थम् अनुपश्यति = one sees as resting in the One | ततः एव च विस्तारम् = and as spreading out from that alone | ब्रह्म सम्पद्यते तदा = then one reaches Brahman""",
    "When a person sees that the many separate forms of beings rest in the One, and spread out from it alone, that person reaches Brahman."),
31: ("""अनादित्वात् = because it has no beginning | निर्गुणत्वात् = and is free from the gunas | परमात्मा अयम् अव्ययः = this unchanging supreme Self | शरीर-स्थः अपि = though living in the body | कौन्तेय = O son of Kunti (Arjuna) | न करोति न लिप्यते = does not act and is not stained""",
    "Because it has no beginning and is free from the gunas, Arjuna, this unchanging supreme Self does not act and is not stained, though it lives in the body."),
32: ("""यथा सर्व-गतम् आकाशम् = as space, which is everywhere | सौक्ष्म्यात् न उपलिप्यते = is not stained, because it is subtle | सर्वत्र अवस्थितः देहे = present everywhere in the body | तथा आत्मा न उपलिप्यते = so the Self is not stained""",
    "As space is everywhere and yet, being subtle, is stained by nothing, so the Self is present everywhere in the body and yet is not stained."),
33: ("""यथा प्रकाशयति एकः रविः = as the one sun lights up | कृत्स्नं लोकम् इमम् = this whole world | क्षेत्रं क्षेत्री तथा कृत्स्नं प्रकाशयति = so the lord of the field lights up the whole field | भारत = O descendant of Bharata (Arjuna)""",
    "As the one sun lights up this whole world, Arjuna, so the lord of the field lights up the whole field."),
34: ("""क्षेत्र-क्षेत्रज्ञयोः एवम् अन्तरम् = the difference between the field and its knower | ज्ञान-चक्षुषा = with the eye of knowledge | भूत-प्रकृति-मोक्षं च = and the freeing of beings from nature | ये विदुः = those who know | यान्ति ते परम् = they reach the supreme""",
    "Those who see with the eye of knowledge the difference between the field and its knower, and how beings are set free from nature, reach the supreme."),
}
